336	    }
337	    this.session.deliver(topic, payload, qos, false);
338	  }
339	
340	  send(buffer) {
341	    if (!this.closed) {
342	      this.socket.write(buffer);
343	    }
344	  }
345	
346	  #touch() {
347	    if (this.timer !== null) {
348	      clearTimeout(this.timer);
349	      this.timer = null;
350	    }
351	    if (this.keepAlive > 0) {
