    const reusedKey = await post(`${started.httpUrl}/devices/device-1/commands`, commandBody({ id: "cmd-2" }), "k1");
    assert.equal(reusedKey.status, 409);
    assert.equal(reusedKey.body.error.code, "conflict");
  });
});

